  const memo = new Map();                       // "i,j" -> edits to turn word1[i..] into word2[j..]
  const edit = (i, j) => {
    if (i === word1.length) return word2.length - j;   // insert the rest
    if (j === word2.length) return word1.length - i;   // delete the rest
    const key = i + "," + j;
    if (memo.has(key)) return memo.get(key);
    const best = word1[i] === word2[j]
      ? edit(i + 1, j + 1)
      : 1 + Math.min(edit(i + 1, j + 1), edit(i + 1, j), edit(i, j + 1));   // replace, delete, insert
    memo.set(key, best);
    return best;
  };
  return edit(0, 0);
}

