int edit(String a, String b, int i, int j) {          // edits to turn a[i..] into b[j..]
    if (i == a.length()) return b.length() - j;       // insert the rest
    if (j == b.length()) return a.length() - i;       // delete the rest
    if (memo[i][j] != null) return memo[i][j];
    int best = a.charAt(i) == b.charAt(j)
        ? edit(a, b, i + 1, j + 1)
        : 1 + Math.min(edit(a, b, i + 1, j + 1), Math.min(edit(a, b, i + 1, j), edit(a, b, i, j + 1)));   // replace, delete, insert
    memo[i][j] = best;
    return best;
}

